    const captureFile = path.join(testDir, "kspec-calls-reset.json");
    const taskRef = "@" + testUlid("TASK");

    // Mock kspec CLI: simulate task with AGENT-FAIL, AGENT-FAIL, AGENT-SUCCESS notes.
