    process.env.KSPEC_CAPTURE_FILE = captureFile;
    try {
      const agent = makeTestAgent({
        adapter: "always-fail-acp",
        budget: { max_tasks: 3, timeout_minutes: 30 },
      } as Partial<Agent>);

      await runInvocation({
