// AC: @agent-invocation-lifecycle ac-9
describe("Consecutive failure threshold and task blocking", () => {
  let testDir: string;

  beforeEach(async () => {
    testDir = await createTempDir("kspec-invoc-ac9-");
    registerAdapter("always-fail-acp", {
      command: "node",
