import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import * as path from "node:path";
import { runInvocation } from "../src/agent-runtime/invocation.js";
import { registerAdapter } from "../src/agents/adapters.js";
import { ACPClient } from "../src/acp/index.js";
import { testUlid, createTempDir, cleanupTempDir } from "./helpers/cli.js";
import type { Agent } from "../src/schema/meta.js";

const MOCK_ACP = path.join(__dirname, "mocks", "acp-mock.js");

function makeTestAgent(overrides: Partial<Agent> = {}): Agent {
  return {
    _ulid: testUlid("AGNT"),
    id: "test-worker",
    name: "Test Worker Agent",
    type: "worker",
    adapter: "slow-mock-acp",
    skills: [],
    auto_approve: false,
    budget: { max_tasks: 10, timeout_minutes: 30 },
    ...overrides,
  };
}

describe("cancel debug", () => {
  let testDir: string;

  beforeEach(async () => {
    testDir = await createTempDir("kspec-cancel-debug-");
    registerAdapter("slow-mock-acp", {
      command: "node",
      args: [MOCK_ACP],
      env: { MOCK_ACP_DELAY_MS: "10000" },
      description: "Slow mock ACP agent for timeout tests",
    });
  });

  afterEach(async () => {
    await cleanupTempDir(testDir);
  });

  it("should call cancel and log", async () => {
    let cancelCalled = false;
    let cancelCalledWith: string | undefined;

    const cancelSpy = vi.spyOn(ACPClient.prototype, "cancel").mockImplementation(async (sessionId) => {
      console.log("CANCEL SPY CALLED with:", sessionId);
      cancelCalled = true;
      cancelCalledWith = sessionId;
    });

    const agent = makeTestAgent({ adapter: "slow-mock-acp" });

    let result: any;
    try {
      result = await runInvocation({
        agent,
        specDir: testDir,
        cwd: process.cwd(),
        taskRef: "@" + testUlid("TASK"),
        prompt: "Test cancel dispatch debug",
        trigger: "task.ready",
        timeoutMinutes: 3 / 60, // 3 seconds
      });
    } finally {
      cancelSpy.mockRestore();
    }

    console.log("result.outcome:", result?.outcome);
    console.log("cancelCalled:", cancelCalled);
    console.log("cancelSpy.mock.calls:", cancelSpy.mock.calls);

    expect(cancelCalled).toBe(true);
    expect(cancelCalledWith).toBeDefined();
  });
});

