/**
 * Agent Invocation Lifecycle
 *
 * Per-invocation session creation, ACP agent spawn, prompt delivery,
 * event logging, timeout handling, and structured completion tracking.
 *
 * This is the core building block used by both the dispatch engine and
 * CLI one-shot mode. Each invocation creates an isolated session with
 * its own event log and metadata.
 *
 * AC: @agent-invocation-lifecycle ac-1 through ac-9
 */

import * as path from "node:path";
import { spawnSync } from "node:child_process";
import { ulid } from "ulid";
import type { Agent } from "../schema/meta.js";
import { buildPromptWithSkills } from "./prompts.js";
import { resolveAdapter } from "../agents/adapters.js";
import { spawnAndInitialize } from "../agents/spawner.js";
import type { SpawnedAgent } from "../agents/spawner.js";
import type { SessionUpdate } from "../acp/index.js";
import {
  createSession,
  closeSession,
  appendEvent,
  injectEnvForAdapter,
  removeEnvForAdapter,
} from "../sessions/store.js";
import type { SessionMetadata, SessionTrigger } from "../sessions/types.js";

// ─── Constants ────────────────────────────────────────────────────────────────

const DEFAULT_KSPEC_CLI_PATH = path.resolve(
  path.dirname(new URL(import.meta.url).pathname),
  "../../bin/kspec.cjs",
);

// ─── Types ────────────────────────────────────────────────────────────────────

/**
 * Options for running a single agent invocation.
 */
export interface InvocationOptions {
  /** The agent definition describing capabilities and configuration */
  agent: Agent;
  /** The spec directory (.kspec/) */
  specDir: string;
  /** Working directory for spawned agent */
  cwd: string;
  /** Task reference being worked on (e.g., "@01KJP277A") */
  taskRef: string;
  /** The prompt to send to the agent */
  prompt: string;
  /** Trigger source for this invocation */
  trigger: SessionTrigger;
  /** Timeout in minutes (overrides agent.budget.timeout_minutes if set) */
  timeoutMinutes?: number;
  /** Whether to use auto-approve (yolo) args for adapter */
  autoApprove?: boolean;
  /** Extra environment variables for the spawned agent */
  env?: Record<string, string>;
  /** Called for each streaming update from the agent */
  onUpdate?: (update: SessionUpdate) => void;
  /** Path to kspec CLI (defaults to resolved bin/kspec.cjs) */
  kspecCliPath?: string;
}

/**
 * Result of a completed agent invocation.
 */
export interface InvocationResult {
  /** Session that was created for this invocation */
  session: SessionMetadata;
  /** How the invocation ended */
  outcome: "success" | "timed_out" | "failed";
  /** Stop reason from ACP (e.g., "end_turn") if the invocation completed */
  stopReason?: string;
  /** Error message if the invocation failed */
  error?: string;
  /** Total duration in milliseconds */
  durationMs: number;
}

/**
 * Internal state tracked during invocation execution.
 */
interface InvocationState {
  sessionId: string;
  specDir: string;
  taskRef: string;
  adapterId: string;
  previousEnvValue?: string | null;
  agent: SpawnedAgent | null;
  acpSessionId: string | null;
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Run a kspec CLI command synchronously.
 */
function runKspecCli(args: string[], cwd: string, kspecCliPath: string): { stdout: string; stderr: string; status: number | null } {
  const result = spawnSync(process.execPath, [kspecCliPath, ...args], {
    encoding: "utf-8",
    stdio: "pipe",
    cwd,
  });
  return {
    stdout: result.stdout ?? "",
    stderr: result.stderr ?? "",
    status: result.status,
  };
}

/**
 * Add a note to a task via kspec CLI.
 */
function addTaskNote(taskRef: string, note: string, cwd: string, kspecCliPath: string): void {
  runKspecCli(["task", "note", taskRef, note], cwd, kspecCliPath);
}

/**
 * Block a task via kspec CLI.
 */
function blockTask(taskRef: string, reason: string, cwd: string, kspecCliPath: string): void {
  runKspecCli(["task", "block", taskRef, "--reason", reason], cwd, kspecCliPath);
}

/**
 * Get the consecutive failure count for a task from its notes.
 * Looks for AGENT-FAIL notes added by previous invocations.
 */
function getConsecutiveFailureCount(taskRef: string, cwd: string, kspecCliPath: string): number {
  const result = runKspecCli(["task", "get", taskRef, "--json"], cwd, kspecCliPath);
  if (result.status !== 0) return 0;

  try {
    const task = JSON.parse(result.stdout);
    const notes: Array<{ content: string }> = task.notes ?? [];
    // Count consecutive AGENT-FAIL notes from the end
    let count = 0;
    for (let i = notes.length - 1; i >= 0; i--) {
      if (notes[i].content?.includes("[AGENT-FAIL]")) {
        count++;
      } else {
        break;
      }
    }
    return count;
  } catch {
    return 0;
  }
}

/**
 * Dispose a spawned agent, terminating the process if running.
 * AC: @agent-invocation-lifecycle ac-8
 */
function disposeAgent(agent: SpawnedAgent | null): null {
  if (agent) {
    try {
      agent.kill("SIGTERM");
    } catch {
      // Best-effort termination
    }
  }
  return null;
}

// ─── Core Invocation ──────────────────────────────────────────────────────────

/**
 * Run a single agent invocation for a task.
 *
 * Creates a session, spawns the agent, injects KSPEC_SESSION_ID,
 * sends the prompt, streams events, and closes the session on completion.
 *
 * AC: @agent-invocation-lifecycle ac-1 through ac-9
 */
export async function runInvocation(options: InvocationOptions): Promise<InvocationResult> {
  const {
    agent,
    specDir,
    cwd,
    taskRef,
    trigger,
    autoApprove = agent.auto_approve,
    env = {},
    onUpdate,
    kspecCliPath = DEFAULT_KSPEC_CLI_PATH,
  } = options;

  const startTime = Date.now();
  const sessionId = ulid();

  // Resolve adapter
  const adapterId = agent.adapter ?? "claude-agent-acp";
  const adapter = resolveAdapter(adapterId);

  // Build extra args for auto-approve
  const extraArgs = autoApprove ? (adapter.autoApproveArgs ?? []) : [];

  // Resolve timeout: option overrides agent budget
  const timeoutMinutes =
    options.timeoutMinutes ??
    agent.budget?.timeout_minutes ??
    30;
  const timeoutMs = timeoutMinutes * 60 * 1000;

  // Resolve skill content for prompt
  // AC: @agent-invocation-lifecycle ac-7
  const fullPrompt = await buildPromptWithSkills({
    basePrompt: options.prompt,
    skillIds: agent.skills ?? [],
    specDir,
  });

  // Capture the pre-existing KSPEC_SESSION_ID so we can restore it in finally.
  // AC: @agent-invocation-lifecycle ac-8
  const previousKspecSessionId = process.env.KSPEC_SESSION_ID;

  const state: InvocationState = {
    sessionId,
    specDir,
    taskRef,
    adapterId,
    previousEnvValue: undefined,
    agent: null,
    acpSessionId: null,
  };

  // ─── Create session ───────────────────────────────────────────────────────
  // AC: @agent-invocation-lifecycle ac-1
  const session = await createSession(specDir, {
    id: sessionId,
    agent_type: adapterId,
    agent_id: agent.id,
    trigger,
    task_id: taskRef,
  });

  // ─── Log agent.dispatched event ───────────────────────────────────────────
  await appendEvent(specDir, {
    type: "agent.dispatched",
    session_id: sessionId,
    data: {
      task_id: taskRef,
      agent_id: agent.id,
      adapter: adapterId,
      trigger,
    },
  });

  try {
    // ─── Inject KSPEC_SESSION_ID ──────────────────────────────────────────
    // AC: @agent-invocation-lifecycle ac-2
    const injectionResult = await injectEnvForAdapter(adapterId, sessionId);
    state.previousEnvValue = injectionResult?.previousValue;
    process.env.KSPEC_SESSION_ID = sessionId;

    // ─── Spawn agent ──────────────────────────────────────────────────────
    state.agent = await spawnAndInitialize(adapter, {
      cwd,
      env: {
        ...env,
        KSPEC_SESSION_ID: sessionId,
      },
      extraArgs,
    });

    // ─── Create ACP session ───────────────────────────────────────────────
    state.acpSessionId = await state.agent.client.newSession({
      cwd,
      mcpServers: [],
    });

    // ─── Log agent.started event ──────────────────────────────────────────
    await appendEvent(specDir, {
      type: "agent.started",
      session_id: sessionId,
      data: {
        task_id: taskRef,
        agent_id: agent.id,
        acp_session_id: state.acpSessionId,
      },
    });

    // ─── Register update handler ──────────────────────────────────────────
    // AC: @agent-invocation-lifecycle ac-6
    const updateHandler = async (acpSessionId: string, update: SessionUpdate) => {
      if (acpSessionId !== state.acpSessionId) return;

      // Log event to JSONL (with blob externalization from store.ts)
      await appendEvent(specDir, {
        type: "session.update",
        session_id: sessionId,
        data: update,
      });

      onUpdate?.(update);
    };

    state.agent.client.on("update", updateHandler);

    // ─── Send prompt with timeout ─────────────────────────────────────────
    // AC: @agent-invocation-lifecycle ac-3
    let timeoutHandle: ReturnType<typeof setTimeout> | undefined;
    const timeoutPromise = new Promise<never>((_, reject) => {
      timeoutHandle = setTimeout(() => {
        reject(new InvocationTimeoutError(timeoutMinutes));
      }, timeoutMs);
    });

    const promptPromise = state.agent.client.prompt({
      sessionId: state.acpSessionId,
      prompt: [{ type: "text", text: fullPrompt }],
    });

    let promptResult: Awaited<typeof promptPromise>;
    try {
      promptResult = await Promise.race([promptPromise, timeoutPromise]);
    } finally {
      // Clear the timeout handle to prevent timer leaks whether prompt
      // resolves normally or the timeout fires.
      clearTimeout(timeoutHandle);
    }

    // ─── Log agent.completed event ────────────────────────────────────────
    // AC: @agent-invocation-lifecycle ac-4
    const durationMs = Date.now() - startTime;
    await appendEvent(specDir, {
      type: "agent.completed",
      session_id: sessionId,
      data: {
        task_id: taskRef,
        outcome: "success",
        stop_reason: promptResult.stopReason,
        duration_ms: durationMs,
      },
    });

    // ─── Close session as completed ───────────────────────────────────────
    const finalSession = await closeSession(specDir, sessionId, "completed", "Invocation completed normally");

    // Add success note to reset consecutive failure streak
    // AC: @agent-invocation-lifecycle ac-9
    addTaskNote(
      taskRef,
      `[AGENT-SUCCESS] Invocation completed successfully`,
      cwd,
      kspecCliPath,
    );

    return {
      session: finalSession ?? session,
      outcome: "success",
      stopReason: promptResult.stopReason,
      durationMs,
    };
  } catch (err) {
    const durationMs = Date.now() - startTime;

    if (err instanceof InvocationTimeoutError) {
      // ─── Handle timeout ──────────────────────────────────────────────
      // AC: @agent-invocation-lifecycle ac-3
      try {
        if (state.acpSessionId && state.agent) {
          await state.agent.client.cancel(state.acpSessionId);
        }
      } catch {
        // Best-effort cancel
      }

      await appendEvent(specDir, {
        type: "agent.timeout",
        session_id: sessionId,
        data: {
          task_id: taskRef,
          timeout_minutes: timeoutMinutes,
          duration_ms: durationMs,
        },
      });

      const finalSession = await closeSession(specDir, sessionId, "timed_out", `Timeout after ${timeoutMinutes} minutes`);

      // Add timeout note to task
      addTaskNote(
        taskRef,
        `[AGENT-TIMEOUT] Invocation timed out after ${timeoutMinutes} minutes`,
        cwd,
        kspecCliPath,
      );

      return {
        session: finalSession ?? session,
        outcome: "timed_out",
        error: err.message,
        durationMs,
      };
    }

    // ─── Handle failure ──────────────────────────────────────────────────
    // AC: @agent-invocation-lifecycle ac-5
    const errorMessage = err instanceof Error ? err.message : String(err);

    await appendEvent(specDir, {
      type: "agent.failed",
      session_id: sessionId,
      data: {
        task_id: taskRef,
        error: errorMessage,
        duration_ms: durationMs,
      },
    });

    const finalSession = await closeSession(specDir, sessionId, "failed", `Invocation failed: ${errorMessage}`);

    // Add failure note to task
    addTaskNote(
      taskRef,
      `[AGENT-FAIL] Invocation failed: ${errorMessage}`,
      cwd,
      kspecCliPath,
    );

    // ─── Check retry threshold ────────────────────────────────────────────
    // AC: @agent-invocation-lifecycle ac-9
    const retryLimit = agent.budget?.max_tasks ?? 3;
    const consecutiveFailures = getConsecutiveFailureCount(taskRef, cwd, kspecCliPath);

    if (consecutiveFailures >= retryLimit) {
      blockTask(
        taskRef,
        `Agent ${agent.id} failed ${consecutiveFailures} consecutive times: ${errorMessage}`,
        cwd,
        kspecCliPath,
      );
    }

    return {
      session: finalSession ?? session,
      outcome: "failed",
      error: errorMessage,
      durationMs,
    };
  } finally {
    // ─── Cleanup ──────────────────────────────────────────────────────────
    // AC: @agent-invocation-lifecycle ac-8

    // End ACP session
    if (state.acpSessionId && state.agent) {
      try {
        state.agent.client.endSession(state.acpSessionId);
      } catch {
        // Best-effort
      }
    }

    // Terminate agent process
    state.agent = disposeAgent(state.agent);

    // Restore env injection
    await removeEnvForAdapter(adapterId, state.previousEnvValue);

    // Restore process.env.KSPEC_SESSION_ID to its pre-invocation value.
    // AC: @agent-invocation-lifecycle ac-8
    if (previousKspecSessionId === undefined) {
      delete process.env.KSPEC_SESSION_ID;
    } else {
      process.env.KSPEC_SESSION_ID = previousKspecSessionId;
    }
  }
}

// ─── Error Types ──────────────────────────────────────────────────────────────

/**
 * Thrown when an invocation exceeds its configured timeout.
 */
export class InvocationTimeoutError extends Error {
  constructor(public readonly timeoutMinutes: number) {
    super(`Agent invocation timed out after ${timeoutMinutes} minutes`);
    this.name = "InvocationTimeoutError";
  }
}

/**
 * Agent instruction generation commands.
 *
 * AC: @agent-instruction-gen ac-1 - kspec agents generate creates kspec-agents.md in project root
 * AC: @agent-instruction-gen ac-2 - output includes Finding Information table with row per skill
 * AC: @agent-instruction-gen ac-3 - output includes conventions section listing rules by domain
 * AC: @agent-instruction-gen ac-4 - output contains freshness comment with kspec version and timestamp
 * AC: @agent-instruction-gen ac-5 - kspec agents status reports stale when not regenerated after meta changes
 *
 * AC: @agents-cli ac-1 - kspec agents generate writes kspec-agents.md to project root
 * AC: @agents-cli ac-2 - kspec agents generate --dry-run prints content without writing
 * AC: @agents-cli ac-3 - kspec agents status reports up to date when current
 * AC: @agents-cli ac-4 - kspec agents status reports stale when meta changed
 *
 * AC: @agent-templates ac-1 - template sections included in output in defined order
 * AC: @agent-templates ac-2 - each template section appears in generated output
 * AC: @agent-templates ac-3 - error if template directory missing or empty
 */

import * as crypto from "node:crypto";
import * as fs from "node:fs/promises";
import { createRequire } from "node:module";
import * as path from "node:path";
import { fileURLToPath } from "node:url";
import chalk from "chalk";
import type { Command } from "commander";
import {
  generateConventionsSummary,
  generateSkillsTable,
  generateWorkflowsSummary,
  initContext,
  loadMetaContext,
  type LoadedConvention,
  type LoadedSkill,
  type LoadedWorkflow,
} from "../../parser/index.js";
import { errors } from "../../strings/errors.js";
import { EXIT_CODES } from "../exit-codes.js";
import { error, output, success } from "../output.js";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Read version from package.json at runtime
const require = createRequire(import.meta.url);
const { version } = require("../../../package.json");

/**
 * File name for generated agent instructions
 */
const GENERATED_FILE_NAME = "kspec-agents.md";

/**
 * Hash file name for tracking freshness
 */
const HASH_FILE_NAME = ".kspec-agents-hash";

/**
 * Templates directory name relative to package root
 */
const TEMPLATES_DIR = "templates/agents-sections";

/**
 * Compute SHA256 hash of content
 */
function computeHash(content: string): string {
  return crypto.createHash("sha256").update(content, "utf-8").digest("hex");
}

/**
 * Load template sections from the templates directory.
 * AC: @agent-templates ac-1 - all template sections included in defined order
 * AC: @agent-templates ac-3 - error if directory missing or empty
 */
export async function loadTemplateSections(packageRoot: string): Promise<string[]> {
  const templatesPath = path.join(packageRoot, TEMPLATES_DIR);

  // Check if templates directory exists
  try {
    await fs.access(templatesPath);
  } catch {
    throw new Error(
      `Templates directory not found at: ${templatesPath}. ` +
        `Expected templates/agents-sections/ directory with section markdown files.`,
    );
  }

  // Read directory contents
  const entries = await fs.readdir(templatesPath, { withFileTypes: true });
  const mdFiles = entries
    .filter((e) => e.isFile() && e.name.endsWith(".md"))
    .map((e) => e.name)
    .sort(); // Sort to ensure consistent ordering by filename prefix

  if (mdFiles.length === 0) {
    throw new Error(
      `Templates directory is empty: ${templatesPath}. ` +
        `Expected markdown files for agent instruction sections.`,
    );
  }

  // Load each template in order
  const sections: string[] = [];
  for (const filename of mdFiles) {
    const filePath = path.join(templatesPath, filename);
    const content = await fs.readFile(filePath, "utf-8");
    sections.push(content.trim());
  }

  return sections;
}

/**
 * Get the package root directory (where templates/ is located)
 */
export function getPackageRoot(): string {
  // Navigate from dist/cli/commands/ to package root
  return path.resolve(__dirname, "..", "..", "..");
}

/**
 * Generate a hash of the meta content that affects the generated file.
 * This is used to detect if the generated file is stale.
 */
export function computeMetaHash(
  skills: LoadedSkill[],
  conventions: LoadedConvention[],
  workflows: LoadedWorkflow[],
  templateSections?: string[],
  metaVersion: string = version,
): string {
  // Create a stable representation of the meta content
  // AC: @cross-platform-and-version-robustness ac-4 - includes templates for staleness detection
  const data: Record<string, unknown> = {
    version: metaVersion,
    skills: skills.map((s) => ({
      id: s.id,
      name: s.name,
      description: s.description,
    })),
    conventions: conventions.map((c) => ({
      domain: c.domain,
      rules: c.rules,
      examples: (c.examples ?? []).map((e) => ({ good: e.good, bad: e.bad })),
    })),
    workflows: workflows.map((w) => ({
      id: w.id,
      trigger: w.trigger,
      description: w.description,
    })),
  };
  if (templateSections && templateSections.length > 0) {
    data.templates = templateSections;
  }
  return computeHash(JSON.stringify(data));
}

/**
 * Generate the freshness comment.
 * AC: @agent-instruction-gen ac-4 - freshness comment with kspec version and timestamp
 */
function generateFreshnessComment(timestamp: string): string {
  return `<!-- Generated by kspec v${version} at ${timestamp} -->\n<!-- Do not edit manually - regenerate with: kspec agents generate -->\n\n`;
}

/**
 * Generate the full kspec-agents.md content
 * AC: @agent-templates ac-1 - template sections included in output in defined order
 * AC: @agent-templates ac-2 - each template section appears in generated output
 */
export async function generateAgentsContent(
  skills: LoadedSkill[],
  conventions: LoadedConvention[],
  workflows: LoadedWorkflow[],
  timestamp: string,
  templateSections: string[],
): Promise<string> {
  const sections: string[] = [];

  // AC: @agent-instruction-gen ac-4 - freshness comment
  sections.push(generateFreshnessComment(timestamp));

  // Header
  sections.push("# kspec Agent Instructions\n");
  sections.push(
    "This file is auto-generated from kspec meta. Include it in your AGENTS.md or similar agent instruction file.\n\n",
  );

  // AC: @agent-instruction-gen ac-2 - Skills table
  // AC: @agent-instruction-gen ac-3 - Conventions section
  // Ensure blank line between each data section for valid markdown
  const dataSections = [
    generateSkillsTable(skills),
    generateConventionsSummary(conventions),
    generateWorkflowsSummary(workflows),
  ].filter(Boolean);

  for (const section of dataSections) {
    // Ensure each section is preceded by a blank line
    if (!sections[sections.length - 1]?.endsWith("\n\n")) {
      sections.push("\n");
    }
    sections.push(section);
  }

  // AC: @agent-templates ac-1, ac-2 - Include template sections in order
  if (templateSections.length > 0) {
    sections.push("\n");
    for (const section of templateSections) {
      sections.push(section);
      sections.push("\n\n");
    }
  }

  return sections.join("");
}

/**
 * Result of checking agent file status
 */
interface AgentStatusResult {
  exists: boolean;
  path: string;
  status: "current" | "stale" | "missing";
  metaHash?: string;
  storedHash?: string;
  generatedAt?: string;
}

/**
 * Check the status of the generated agent file.
 * AC: @agent-instruction-gen ac-5 - reports stale when meta has changed
 */
async function checkAgentStatus(
  projectRoot: string,
  metaHash: string,
): Promise<AgentStatusResult> {
  const filePath = path.join(projectRoot, GENERATED_FILE_NAME);
  const hashPath = path.join(projectRoot, ".kspec", HASH_FILE_NAME);

  // Check if file exists
  try {
    await fs.access(filePath);
  } catch {
    return {
      exists: false,
      path: filePath,
      status: "missing",
      metaHash,
    };
  }

  // Check stored hash
  let storedHash: string | undefined;
  let generatedAt: string | undefined;

  try {
    const hashContent = await fs.readFile(hashPath, "utf-8");
    const hashData = JSON.parse(hashContent);
    storedHash = hashData.metaHash;
    generatedAt = hashData.generatedAt;
  } catch {
    // No hash file, treat as stale
    return {
      exists: true,
      path: filePath,
      status: "stale",
      metaHash,
    };
  }

  // Compare hashes
  const isCurrent = storedHash === metaHash;

  return {
    exists: true,
    path: filePath,
    status: isCurrent ? "current" : "stale",
    metaHash,
    storedHash,
    generatedAt,
  };
}

/**
 * Register agent instruction generation commands
 */
export function registerAgentsCommands(program: Command): void {
  const agents = program
    .command("agents")
    .description("Agent instruction generation commands");

  // AC: @agent-instruction-gen ac-1 - kspec agents generate
  // AC: @agent-templates ac-3 - error if template directory missing
  // AC: @trait-dry-run ac-1 through ac-6 - dry-run support
  agents
    .command("generate")
    .description("Generate kspec-agents.md from meta (skills, conventions, workflows)")
    .option("--dry-run", "Show what would be generated without writing files")
    .action(async (options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error(errors.project.noKspecProject);
          process.exit(EXIT_CODES.ERROR);
        }

        // AC: @agent-templates ac-3 - error if templates missing
        const packageRoot = getPackageRoot();
        let templateSections: string[];
        try {
          templateSections = await loadTemplateSections(packageRoot);
        } catch (err) {
          const message =
            err instanceof Error ? err.message : "Unknown error loading templates";
          error(message, {
            suggestion: `Verify that ${TEMPLATES_DIR}/ exists with markdown files.`,
          });
          process.exit(EXIT_CODES.ERROR);
        }

        const metaCtx = await loadMetaContext(ctx);
        const dryRun = options.dryRun || false;
        const timestamp = new Date().toISOString();

        // Generate content - now async due to template loading
        const content = await generateAgentsContent(
          metaCtx.skills,
          metaCtx.conventions,
          metaCtx.workflows,
          timestamp,
          templateSections,
        );

        // Compute meta hash for freshness tracking (includes templates)
        const metaHash = computeMetaHash(
          metaCtx.skills,
          metaCtx.conventions,
          metaCtx.workflows,
          templateSections,
        );

        const outputPath = path.join(ctx.rootDir, GENERATED_FILE_NAME);
        const hashPath = path.join(ctx.rootDir, ".kspec", HASH_FILE_NAME);

        // AC: @agent-instruction-gen ac-6 - skip regeneration when content unchanged
        if (!dryRun) {
          const status = await checkAgentStatus(ctx.rootDir, metaHash);
          if (status.status === "current") {
            output(
              {
                path: outputPath,
                status: "current",
                skipped: true,
              },
              () => {
                success(`${GENERATED_FILE_NAME} is already up to date`);
              },
            );
            return;
          }
        }

        // AC: @trait-dry-run ac-3 - clear indication this is a preview
        if (dryRun) {
          output(
            {
              dry_run: true,
              path: outputPath,
              skills: metaCtx.skills.length,
              conventions: metaCtx.conventions.length,
              workflows: metaCtx.workflows.length,
              templates: templateSections.length,
              content,
            },
            () => {
              console.log(chalk.yellow("DRY RUN - No changes made"));
              console.log();
              console.log(chalk.gray(`Would write to: ${outputPath}`));
              console.log();
              console.log(chalk.gray("--- Generated content ---"));
              console.log(content);
              console.log(chalk.gray("--- End content ---"));
              console.log();
              console.log(
                chalk.yellow("No changes were made. Run without --dry-run to apply."),
              );
            },
          );
          return;
        }

        // AC: @trait-dry-run ac-2 - no files modified in dry run mode
        // Write the generated file
        await fs.writeFile(outputPath, content, "utf-8");

        // Write the hash file for freshness tracking
        await fs.mkdir(path.dirname(hashPath), { recursive: true });
        await fs.writeFile(
          hashPath,
          JSON.stringify(
            {
              metaHash,
              generatedAt: timestamp,
              version,
            },
            null,
            2,
          ),
          "utf-8",
        );

        output(
          {
            path: outputPath,
            skills: metaCtx.skills.length,
            conventions: metaCtx.conventions.length,
            workflows: metaCtx.workflows.length,
            templates: templateSections.length,
            generatedAt: timestamp,
          },
          () => {
            success(`Generated ${GENERATED_FILE_NAME}`, {
              skills: metaCtx.skills.length,
              conventions: metaCtx.conventions.length,
              workflows: metaCtx.workflows.length,
              templates: templateSections.length,
            });
            console.log(chalk.gray(`  Path: ${outputPath}`));
          },
        );
      } catch (err) {
        error("Failed to generate agent instructions", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // AC: @agent-instruction-gen ac-5 - kspec agents status
  agents
    .command("status")
    .description("Check if kspec-agents.md is up to date with meta")
    .action(async () => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error(errors.project.noKspecProject);
