 */
export async function findMetaManifest(
  specDir: string,
): Promise<string | null> {
  // AC: @meta-manifest-discovery ac-1, ac-3 - explicit name has priority
  const priorityPath = path.join(specDir, "kynetic.meta.yaml");
  try {
    await fs.access(priorityPath);
    return priorityPath;
