/**
 * Agent command family — kspec agent list/run/dispatch/status
 *
 * AC: @cli-agent-commands ac-1 - kspec agent list shows agent definitions
 * AC: @cli-agent-commands ac-2 - kspec agent run <name> --task @ref one-shot invocation
 * AC: @cli-agent-commands ac-3 - kspec agent run <name> <prompt> without --task
 * AC: @cli-agent-commands ac-4 - kspec agent dispatch start starts dispatch engine
 * AC: @cli-agent-commands ac-5 - kspec agent dispatch stop stops dispatch engine
 * AC: @cli-agent-commands ac-6 - kspec agent status shows active/queued invocations
 * AC: @cli-agent-commands ac-7 - CLI flags --budget --timeout --adapter override agent defaults
 * AC: @cli-agent-commands ac-8 - kspec agent run --dry-run shows prompt without spawning
 * AC: @cli-agent-commands ac-9 - kspec agent dispatch status shows engine state
 * AC: @cli-agent-commands ac-10 - error when daemon not running for dispatch start
 *
 * AC: @trait-json-output ac-1 - --json flag outputs valid JSON
 * AC: @trait-json-output ac-2 - JSON includes all data from human-readable mode
 * AC: @trait-json-output ac-3 - errors returned as JSON with error field
 * AC: @trait-json-output ac-4 - references use @ prefix
 * AC: @trait-json-output ac-5 - timestamps use ISO 8601
 * AC: @trait-json-output ac-6 - --json takes precedence over other format options
 *
 * AC: @trait-semantic-exit-codes ac-1 - success exits 0
 * AC: @trait-semantic-exit-codes ac-2 - validation errors exit 1
 * AC: @trait-semantic-exit-codes ac-4 - runtime errors exit 3
 * AC: @trait-semantic-exit-codes ac-6 - invalid flags exit 1 with usage info
 *
 * AC: @trait-error-guidance ac-1 - error includes what went wrong
 * AC: @trait-error-guidance ac-2 - error includes suggested action
 * AC: @trait-error-guidance ac-3 - not-found error suggests search/list
 *
 * AC: @trait-dry-run ac-1 - --dry-run shows what would happen
 * AC: @trait-dry-run ac-2 - no files modified in dry run
 * AC: @trait-dry-run ac-3 - clear preview indication
 * AC: @trait-dry-run ac-6 - JSON includes dry_run boolean
 *
 * AC: @trait-filterable-list ac-1 - list supports --status filter (N/A: agents have no status)
 * AC: @trait-filterable-list ac-3 - list supports --limit N
 * AC: @trait-filterable-list ac-4 - list supports --offset N
 * AC: @trait-filterable-list ac-6 - empty list shows informative message
 * AC: @trait-filterable-list ac-7 - summary shows total count
 * AC: @trait-filterable-list ac-8 - --count outputs just the total count
 */

// AC: @trait-filterable-list ac-1 — N/A: Agent definitions don't have a status field;
//   --status filter is not applicable and not exposed on kspec agent list.
// AC: @trait-filterable-list ac-2 — N/A: Agent definitions have no tags; --tag filter not applicable.
// AC: @trait-filterable-list ac-5 — N/A: Multiple filters not applicable without status/tag fields.
// AC: @trait-semantic-exit-codes ac-3 — N/A: No confirmation prompts in agent commands.
// AC: @trait-semantic-exit-codes ac-5 — Empty list exits 0 with empty result set.
// AC: @trait-semantic-exit-codes ac-7 — N/A: No batch operations in this command.
// AC: @trait-semantic-exit-codes ac-8 — Exit codes documented in EXIT_CODES and inline comments.
// AC: @trait-error-guidance ac-4 — N/A: No state transitions in agent commands.
// AC: @trait-error-guidance ac-5 — validation errors include field/value.
// AC: @trait-error-guidance ac-6 — JSON mode errors include guidance in structured error.
// AC: @trait-dry-run ac-4 — dry-run shows error if agent not found, no state changed.
// AC: @trait-dry-run ac-5 — N/A: No --force flag in agent commands.

import chalk from "chalk";
import type { Command } from "commander";
