/**
 * Build daemon URL from PID file.
 * Returns null if daemon is not running or port cannot be determined.
 */
function getDaemonUrl(): string | null {
  const pidManager = new PidFileManager();
  try {
    const port = pidManager.readPort();
    return `http://localhost:${port}`;
  } catch {
    return null;
  }
}

/**
 * Format a dispatch rule summary for display.
 */
function formatDispatchRules(rules: LoadedAgent["dispatch"]): string {
  if (!rules || rules.length === 0) return "none";
  return rules.map((r) => r.on).join(", ");
}

/**
 * Find an agent by ID from the loaded agents list.
 * Returns the agent or null if not found.
 */
function findAgent(
  agentId: string,
  agents: LoadedAgent[],
): LoadedAgent | null {
  return agents.find((a) => a.id === agentId) ?? null;
}

// ─── Command Registration ─────────────────────────────────────────────────────

export function registerAgentCommands(program: Command): void {
  const agent = program
    .command("agent")
    .description("Manage and run agents");

  // ─── kspec agent list ─────────────────────────────────────────────────────
  // AC: @cli-agent-commands ac-1
  // AC: @trait-filterable-list ac-3, ac-4, ac-6, ac-7, ac-8
  agent
    .command("list")
    .description("List all agent definitions")
    .option("--limit <n>", "Maximum number of agents to show", parseInt)
    .option("--offset <n>", "Skip first N agents", parseInt)
    .option("--count", "Output only the total count")
    .action(async (opts) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error(errors.project.noKspecProject);
          process.exit(EXIT_CODES.ERROR);
        }

        const metaCtx = await loadMetaContext(ctx);
        let agents = metaCtx.agents;

        // Apply pagination
        // AC: @trait-filterable-list ac-8 - --count ignores --limit/--offset
        if (opts.count) {
          const count = agents.length;
          output({ count }, () => {
            console.log(count);
          });
          return;
        }

        // AC: @trait-filterable-list ac-4 - --offset N
        if (opts.offset && opts.offset > 0) {
          agents = agents.slice(opts.offset);
        }

        // AC: @trait-filterable-list ac-3 - --limit N
        if (opts.limit && opts.limit > 0) {
          agents = agents.slice(0, opts.limit);
        }

        const total = metaCtx.agents.length;

        // AC: @trait-filterable-list ac-6 - empty list with informative message
        if (total === 0) {
          output(
            { agents: [], total: 0 },
            () => {
              warn("No agent definitions found.");
              console.log(
                chalk.gray(
                  "Add agent definitions to your meta (kynetic.meta.yaml) to get started.",
                ),
              );
            },
          );
          return;
        }

        const agentData = agents.map((a) => ({
          id: a.id,
          name: a.name,
          adapter: a.adapter ?? "claude-agent-acp",
          dispatch_rules: formatDispatchRules(a.dispatch),
          concurrency: a.concurrency?.max_concurrent ?? 1,
          description: a.description,
        }));

        // AC: @trait-filterable-list ac-7 - summary shows total
        output(
          { agents: agentData, total },
          () => {
            console.log(
              chalk.bold(`Agents (${agentData.length}/${total}):`),
            );
            console.log();
            for (const a of agentData) {
              console.log(chalk.cyan(`  ${a.id}`));
              console.log(chalk.gray(`    Name:       ${a.name}`));
              console.log(chalk.gray(`    Adapter:    ${a.adapter}`));
              console.log(
                chalk.gray(`    Dispatch:   ${a.dispatch_rules}`),
              );
              console.log(
                chalk.gray(`    Concurrency: ${a.concurrency}`),
              );
              if (a.description) {
                console.log(chalk.gray(`    Description: ${a.description}`));
              }
              console.log();
            }
            console.log(chalk.gray(`Total: ${total}`));
          },
        );
      } catch (err) {
        error("Failed to list agents", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // ─── kspec agent run ──────────────────────────────────────────────────────
  // AC: @cli-agent-commands ac-2, ac-3, ac-7, ac-8
  // AC: @trait-dry-run ac-1, ac-2, ac-3, ac-4, ac-6
  agent
    .command("run <name> [prompt]")
    .description("Run a one-shot agent invocation")
    .option("--task <ref>", "Task reference to work on")
    .option("--budget <n>", "Budget in minutes (overrides agent default)", parseFloat)
    .option("--timeout <n>", "Timeout in minutes (overrides agent default)", parseFloat)
    .option("--adapter <id>", "Adapter to use (overrides agent default)")
    .option("--dry-run", "Show prompt that would be sent without spawning agent")
    .action(async (name: string, prompt: string | undefined, opts) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error(errors.project.noKspecProject);
          process.exit(EXIT_CODES.ERROR);
        }

        const metaCtx = await loadMetaContext(ctx);

        // AC: @trait-error-guidance ac-1, ac-2, ac-3
        const agentDef = findAgent(name, metaCtx.agents);
        if (!agentDef) {
          const jsonErr = {
            error: `Agent '${name}' not found`,
            suggestion: `Check available agents with: kspec agent list`,
          };
          if (isJsonMode()) {
            output(jsonErr, () => {});
          } else {
            error(`Agent '${name}' not found`, {
              suggestion: "Check available agents with: kspec agent list",
            });
          }
          process.exit(EXIT_CODES.NOT_FOUND);
        }

        // Resolve override fields
        // AC: @cli-agent-commands ac-7
        const resolvedAgent = {
          ...agentDef,
          adapter: opts.adapter ?? agentDef.adapter,
        };

        // Determine the prompt to use
        // AC: @cli-agent-commands ac-2 - with --task, use task-work prompt
        // AC: @cli-agent-commands ac-3 - without --task, use provided prompt
        const taskRef: string = opts.task ?? "";
        const basePrompt = prompt ?? (opts.task ? `/kspec:task-work\n\nWork on task: ${opts.task}` : "");

        if (!basePrompt && !opts.task) {
          const jsonErr = {
            error: "A prompt or --task flag is required",
            suggestion: "Provide a prompt text or use --task <ref> to target a specific task",
          };
          if (isJsonMode()) {
            output(jsonErr, () => {});
          } else {
            error("A prompt or --task flag is required", {
              suggestion: "Provide a prompt text or use --task <ref> to target a specific task",
            });
          }
          process.exit(EXIT_CODES.ERROR);
        }

        // AC: @trait-dry-run ac-1, ac-2, ac-3, ac-4
        if (opts.dryRun) {
          const dryRunData = {
            dry_run: true,
            agent: {
              id: resolvedAgent.id,
              name: resolvedAgent.name,
              adapter: resolvedAgent.adapter ?? "claude-agent-acp",
            },
            task_ref: taskRef || null,
            prompt: basePrompt,
            timeout_minutes: opts.timeout ?? resolvedAgent.budget?.timeout_minutes ?? 30,
          };
          // AC: @trait-dry-run ac-6 - JSON includes dry_run field
          output(dryRunData, () => {
            console.log(chalk.yellow("DRY RUN - No agent will be spawned"));
            console.log();
            console.log(
              chalk.gray(`Agent:   ${resolvedAgent.id} (${resolvedAgent.adapter ?? "claude-agent-acp"})`),
            );
            if (taskRef) {
              console.log(chalk.gray(`Task:    ${taskRef}`));
            }
            console.log(chalk.gray(`Timeout: ${dryRunData.timeout_minutes} minutes`));
            console.log();
            console.log(chalk.gray("--- Prompt that would be sent ---"));
            console.log(basePrompt);
            console.log(chalk.gray("--- End prompt ---"));
            console.log();
            console.log(
              chalk.yellow("No changes were made. Run without --dry-run to execute."),
            );
          });
          return;
        }

        // Run the invocation
        // AC: @cli-agent-commands ac-2, ac-3
        console.log(
          chalk.gray(
            `Spawning agent '${resolvedAgent.id}' via ${resolvedAgent.adapter ?? "claude-agent-acp"}...`,
          ),
        );

        const sessionId = ulid();
        const result = await runInvocation({
          agent: resolvedAgent,
          specDir: ctx.specDir,
          cwd: ctx.rootDir,
          taskRef,
          prompt: basePrompt,
          trigger: "manual",
          timeoutMinutes: opts.timeout ?? opts.budget,
        });

        const resultData = {
          session_id: result.session.id,
          agent_id: resolvedAgent.id,
          task_ref: taskRef || null,
          outcome: result.outcome,
          started_at: result.session.started_at,
          duration_ms: result.durationMs,
          stop_reason: result.stopReason ?? null,
          error: result.error ?? null,
        };

        output(resultData, () => {
          if (result.outcome === "success") {
            success(`Agent invocation completed`, {
              session: result.session.id,
              outcome: result.outcome,
              duration: `${Math.round(result.durationMs / 1000)}s`,
            });
          } else if (result.outcome === "timed_out") {
            warn(
              `Agent invocation timed out after ${opts.timeout ?? resolvedAgent.budget?.timeout_minutes ?? 30} minutes`,
            );
          } else {
            error(`Agent invocation failed: ${result.error ?? "unknown error"}`);
          }
        });

        if (result.outcome !== "success") {
          process.exit(EXIT_CODES.ERROR);
        }
      } catch (err) {
        error("Failed to run agent", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // ─── kspec agent dispatch ─────────────────────────────────────────────────
  const dispatch = agent
    .command("dispatch")
    .description("Manage the agent dispatch engine");

  // kspec agent dispatch start
  // AC: @cli-agent-commands ac-4, ac-10
  dispatch
    .command("start")
    .description("Start the agent dispatch engine")
    .action(async () => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error(errors.project.noKspecProject);
          process.exit(EXIT_CODES.ERROR);
        }

        const daemonUrl = getDaemonUrl();

        // AC: @cli-agent-commands ac-10 - error when daemon not running
        if (!daemonUrl) {
          const jsonErr = {
            error: "Daemon is not running",
            suggestion: "Start the daemon first with: kspec serve",
          };
          if (isJsonMode()) {
            output(jsonErr, () => {});
          } else {
            error("Daemon is not running", {
              suggestion: "Start the daemon first with: kspec serve",
            });
          }
          process.exit(EXIT_CODES.ERROR);
        }

        const response = await fetch(`${daemonUrl}/api/agent/dispatch/start`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "X-Kspec-Dir": ctx.rootDir,
          },
        });

        if (!response.ok) {
          const body = await response.text();
          error(`Failed to start dispatch engine: ${body}`);
          process.exit(EXIT_CODES.ERROR);
        }

        const data = await response.json() as {
          started: boolean;
          reason?: string;
          status: { running: boolean; activeInvocations: number; queuedInvocations: number };
        };

        output(data, () => {
          if (data.started) {
            success("Dispatch engine started");
          } else {
            warn(`Dispatch engine: ${data.reason ?? "already running"}`);
          }
          const s = data.status;
          console.log(
            chalk.gray(
              `  Active: ${s.activeInvocations}, Queued: ${s.queuedInvocations}`,
            ),
          );
        });
      } catch (err) {
        error("Failed to start dispatch engine", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // kspec agent dispatch stop
  // AC: @cli-agent-commands ac-5
  dispatch
    .command("stop")
    .description("Stop the agent dispatch engine")
    .action(async () => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error(errors.project.noKspecProject);
          process.exit(EXIT_CODES.ERROR);
        }

        const daemonUrl = getDaemonUrl();

        if (!daemonUrl) {
          const jsonErr = {
            error: "Daemon is not running",
            suggestion: "Start the daemon first with: kspec serve",
          };
          if (isJsonMode()) {
            output(jsonErr, () => {});
          } else {
            error("Daemon is not running", {
              suggestion: "The daemon must be running to stop the dispatch engine.",
            });
          }
          process.exit(EXIT_CODES.ERROR);
        }

        const response = await fetch(`${daemonUrl}/api/agent/dispatch/stop`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "X-Kspec-Dir": ctx.rootDir,
          },
        });

        if (!response.ok) {
          const body = await response.text();
          error(`Failed to stop dispatch engine: ${body}`);
          process.exit(EXIT_CODES.ERROR);
        }

        const data = await response.json() as { stopped: boolean; reason?: string };

        output(data, () => {
          if (data.stopped) {
            success("Dispatch engine stopped");
          } else {
            warn(`Dispatch engine: ${data.reason ?? "not running"}`);
          }
        });
      } catch (err) {
        error("Failed to stop dispatch engine", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // kspec agent dispatch status
  // AC: @cli-agent-commands ac-9
  dispatch
    .command("status")
    .description("Show dispatch engine status")
    .action(async () => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error(errors.project.noKspecProject);
          process.exit(EXIT_CODES.ERROR);
        }

        const daemonUrl = getDaemonUrl();

        if (!daemonUrl) {
          const statusData = {
            daemon_running: false,
            dispatch_running: false,
            activeInvocations: 0,
            queuedInvocations: 0,
            agent_definitions: 0,
          };
          output(statusData, () => {
            warn("Daemon is not running");
            console.log(chalk.gray("  Start the daemon with: kspec serve"));
          });
          return;
        }

        // Fetch dispatch status from daemon
        // AC: @cli-agent-commands ac-9 - shows enabled, active, queued, loaded agents
        const [dispatchResponse, metaCtx] = await Promise.all([
          fetch(`${daemonUrl}/api/agent/dispatch/status`, {
            headers: { "X-Kspec-Dir": ctx.rootDir },
          }),
          loadMetaContext(ctx),
        ]);

        let dispatchStatus: {
          running: boolean;
          activeInvocations: number;
          queuedInvocations: number;
        } = { running: false, activeInvocations: 0, queuedInvocations: 0 };

        if (dispatchResponse.ok) {
          dispatchStatus = await dispatchResponse.json() as typeof dispatchStatus;
        }

        const statusData = {
          daemon_running: true,
          dispatch_running: dispatchStatus.running,
          active_invocations: dispatchStatus.activeInvocations,
          queued_invocations: dispatchStatus.queuedInvocations,
          agent_definitions: metaCtx.agents.length,
        };

        output(statusData, () => {
          const dispatchLabel = dispatchStatus.running
            ? chalk.green("running")
            : chalk.yellow("stopped");
          console.log(`Dispatch engine: ${dispatchLabel}`);
          console.log(
            chalk.gray(`  Active invocations: ${dispatchStatus.activeInvocations}`),
          );
          console.log(
            chalk.gray(`  Queued invocations: ${dispatchStatus.queuedInvocations}`),
          );
          console.log(
            chalk.gray(`  Loaded agent definitions: ${metaCtx.agents.length}`),
          );
        });
      } catch (err) {
        error("Failed to get dispatch status", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // ─── kspec agent status ───────────────────────────────────────────────────
  // AC: @cli-agent-commands ac-6
  agent
    .command("status")
    .description("Show active and queued agent invocations")
    .action(async () => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error(errors.project.noKspecProject);
          process.exit(EXIT_CODES.ERROR);
        }

        const daemonUrl = getDaemonUrl();

        if (!daemonUrl) {
          output(
            { daemon_running: false, active: [], queued: 0 },
            () => {
              warn("Daemon is not running — no invocation status available");
              console.log(chalk.gray("  Start the daemon with: kspec serve"));
            },
          );
          return;
        }

        // Query dispatch engine status from daemon
        // AC: @cli-agent-commands ac-6 - shows session IDs, agent names, task refs, elapsed time
        const response = await fetch(`${daemonUrl}/api/agent/dispatch/status`, {
          headers: { "X-Kspec-Dir": ctx.rootDir },
        });

        if (!response.ok) {
          error("Failed to fetch invocation status from daemon");
          process.exit(EXIT_CODES.ERROR);
        }

        const data = await response.json() as {
          running: boolean;
          activeInvocations: number;
          queuedInvocations: number;
        };

        // Note: the daemon currently exposes aggregate counts.
        // Per-invocation detail (session IDs, task refs, elapsed time) requires
        // session store access from the CLI side.
        const statusData = {
          daemon_running: true,
          dispatch_running: data.running,
          active_count: data.activeInvocations,
          queued_count: data.queuedInvocations,
        };

        output(statusData, () => {
          if (!data.running) {
            warn("Dispatch engine is not running");
            console.log(chalk.gray("  Start with: kspec agent dispatch start"));
            return;
          }

          console.log(chalk.bold("Agent Invocations:"));
          console.log(
            chalk.gray(`  Active:  ${data.activeInvocations}`),
          );
          console.log(
            chalk.gray(`  Queued:  ${data.queuedInvocations}`),
          );

          if (data.activeInvocations === 0 && data.queuedInvocations === 0) {
            console.log();
            console.log(chalk.gray("  No active or queued invocations."));
          }
        });
      } catch (err) {
        error("Failed to get agent status", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });
}

