 * CLI Agent Commands tests.
 *
 * Tests for kspec agent list/run/dispatch/status subcommands.
 *
 * Task: @implement-cli-agent-commands
 * Spec: @cli-agent-commands
 */

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import {
  kspec,
  kspecJson,
  setupTempFixtures,
  cleanupTempDir,
  initGitRepo,
} from "./helpers/cli.js";

// ─── Setup ────────────────────────────────────────────────────────────────────

let tempDir: string;

beforeEach(async () => {
  tempDir = await setupTempFixtures();
  initGitRepo(tempDir);
});

afterEach(async () => {
  await cleanupTempDir(tempDir);
});

// ─── AC-1: kspec agent list ───────────────────────────────────────────────────

// AC: @cli-agent-commands ac-1
describe("AC-1: kspec agent list shows agent definitions", () => {
  it("should list agent definitions with id, adapter, dispatch rules, and concurrency", () => {
    const result = kspec("agent list", tempDir);
    expect(result.exitCode).toBe(0);
    // Fixtures have test-agent and review-agent
    expect(result.stdout).toContain("test-agent");
    expect(result.stdout).toContain("review-agent");
  });

  // AC: @trait-json-output ac-1
  it("should output valid JSON with --json flag", () => {
    const data = kspecJson<{ items: unknown[]; total: number }>("agent list", tempDir);
    expect(Array.isArray(data.items)).toBe(true);
    expect(typeof data.total).toBe("number");
  });

  // AC: @trait-json-output ac-2
  it("JSON includes all data available in human-readable mode", () => {
    const data = kspecJson<{
      items: Array<{ id: string; name: string; adapter: string; dispatch: unknown[]; concurrency: unknown }>;
      total: number;
    }>("agent list", tempDir);
    expect(data.items.length).toBeGreaterThan(0);
    const first = data.items[0];
    expect(first).toHaveProperty("id");
    expect(first).toHaveProperty("name");
    expect(first).toHaveProperty("adapter");
    expect(first).toHaveProperty("dispatch");
    expect(first).toHaveProperty("concurrency");
  });

  // AC: @trait-filterable-list ac-3
  it("should respect --limit flag", () => {
    const data = kspecJson<{ items: unknown[]; total: number }>("agent list --limit 1", tempDir);
    expect(data.items.length).toBeLessThanOrEqual(1);
    expect(data.total).toBeGreaterThanOrEqual(1);
  });

  // AC: @trait-filterable-list ac-4
  it("should respect --offset flag", () => {
    const full = kspecJson<{ items: Array<{ id: string }> }>("agent list", tempDir);
    const offset = kspecJson<{ items: Array<{ id: string }> }>("agent list --offset 1", tempDir);
    if (full.items.length > 1) {
      expect(offset.items[0]?.id).toBe(full.items[1]?.id);
    }
  });

  // AC: @trait-filterable-list ac-6
  it("should show informative message when no agents match", () => {
    // Use --status with a value that doesn't match any agent's automation field
    const result = kspec("agent list --status nonexistent-status", tempDir);
    expect(result.exitCode).toBe(0);
    // Should output empty list
    const data = JSON.parse(result.stdout);
    expect(data.items.length).toBe(0);
  });

  // AC: @trait-filterable-list ac-7
  it("should show total count in summary", () => {
    const data = kspecJson<{ items: unknown[]; total: number }>("agent list", tempDir);
    expect(data.total).toBeGreaterThan(0);
  });

  // AC: @trait-filterable-list ac-8
  it("--count outputs only the total count as integer", () => {
    const result = kspec("agent list --count", tempDir);
    expect(result.exitCode).toBe(0);
    const data = JSON.parse(result.stdout);
    expect(typeof data.count).toBe("number");
  });

  // AC: @trait-semantic-exit-codes ac-1
  it("should exit 0 on success", () => {
    const result = kspec("agent list", tempDir);
    expect(result.exitCode).toBe(0);
  });

  // AC: @trait-semantic-exit-codes ac-5
  it("should exit 0 with empty result set when no agents match filters", () => {
    const result = kspec("agent list --status bogus-filter", tempDir);
    expect(result.exitCode).toBe(0);
  });
});

// ─── AC-8: kspec agent run --dry-run ─────────────────────────────────────────

// AC: @cli-agent-commands ac-8
describe("AC-8: kspec agent run --dry-run shows prompt without spawning", () => {
  // AC: @trait-dry-run ac-1, ac-2, ac-3
  it("shows what would be sent without spawning agent", () => {
    const result = kspec(
      'agent run test-agent "custom prompt text" --dry-run',
      tempDir,
    );
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain("DRY RUN");
    expect(result.stdout).toContain("custom prompt text");
  });

  // AC: @cli-agent-commands ac-3
  it("accepts custom prompt text without --task flag", () => {
    const result = kspec(
      'agent run test-agent "my custom prompt" --dry-run',
      tempDir,
    );
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain("my custom prompt");
  });

  // AC: @cli-agent-commands ac-2
  it("accepts --task flag for task-bound invocation", () => {
    const result = kspec(
      "agent run test-agent --task @some-task-ref --dry-run",
      tempDir,
    );
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain("DRY RUN");
    expect(result.stdout).toContain("some-task-ref");
  });

  // AC: @trait-dry-run ac-6
  it("JSON output includes dry_run boolean field", () => {
    const data = kspecJson<{ dry_run: boolean; agent_id: string; prompt: string }>(
      'agent run test-agent "test prompt" --dry-run',
      tempDir,
    );
    expect(data.dry_run).toBe(true);
    expect(data.agent_id).toBe("test-agent");
    expect(data.prompt).toContain("test prompt");
  });

  // AC: @trait-dry-run ac-2
  it("no files are modified in dry run mode", async () => {
    const { readdir } = await import("node:fs/promises");
    const { join } = await import("node:path");
    const sessionsDir = join(tempDir, "sessions");
    const beforeEntries = await readdir(sessionsDir).catch(() => []);

    kspec('agent run test-agent "test" --dry-run', tempDir);

    const afterEntries = await readdir(sessionsDir).catch(() => []);
    expect(afterEntries.length).toBe(beforeEntries.length);
  });

  // AC: @trait-error-guidance ac-3
  it("shows error with suggestion when agent not found", () => {
    const result = kspec("agent run nonexistent-agent --dry-run", tempDir, {
      expectFail: true,
    });
    expect(result.exitCode).not.toBe(0);
    expect(result.stderr).toContain("nonexistent-agent");
  });

  // AC: @cli-agent-commands ac-7
  it("--adapter flag overrides agent default", () => {
    const data = kspecJson<{ dry_run: boolean; adapter?: string; agent_id: string }>(
      'agent run test-agent "test" --adapter custom-adapter --dry-run',
      tempDir,
    );
    expect(data.dry_run).toBe(true);
  });
});

// ─── AC-10: Dispatch commands require daemon ──────────────────────────────────

// AC: @cli-agent-commands ac-10
describe("AC-10: dispatch start errors when daemon not running", () => {
  it("shows error message when daemon is not running", () => {
    // Daemon is not started in test environment
    const result = kspec("agent dispatch start", tempDir, { expectFail: true });
    expect(result.exitCode).not.toBe(0);
    expect(result.stderr.toLowerCase()).toMatch(/daemon.*not running|not running.*daemon/);
  });

  it("includes suggestion to start daemon with kspec serve", () => {
    const result = kspec("agent dispatch start", tempDir, { expectFail: true });
    expect(result.stderr).toContain("kspec serve");
  });

  // AC: @trait-json-output ac-3
  it("returns JSON error object when --json and daemon not running", () => {
    const result = kspec("agent dispatch start --json", tempDir, {
      expectFail: true,
    });
    // Should have valid JSON output even on error
    try {
      const data = JSON.parse(result.stdout || result.stderr);
      expect(data).toHaveProperty("error");
    } catch {
      // If no JSON output, the error should still mention daemon
      expect(result.stderr.toLowerCase()).toMatch(/daemon/);
    }
  });
});

// ─── AC-9: kspec agent dispatch status ───────────────────────────────────────

// AC: @cli-agent-commands ac-9
describe("AC-9: kspec agent dispatch status shows engine state", () => {
  it("shows dispatch status (daemon offline case)", () => {
    const result = kspec("agent dispatch status", tempDir);
    // Should succeed even when daemon is offline (shows offline state)
    expect(result.exitCode).toBe(0);
    const data = JSON.parse(result.stdout);
    // When daemon offline, shows running: false
    expect(data).toHaveProperty("running");
    expect(data.running).toBe(false);
  });

  it("includes agent definitions count in output", () => {
    const result = kspec("agent dispatch status --json", tempDir);
    expect(result.exitCode).toBe(0);
    const data = JSON.parse(result.stdout);
    // Should show agent definition info
    expect(data).toHaveProperty("agents");
  });
});

// ─── AC-6: kspec agent status ────────────────────────────────────────────────

// AC: @cli-agent-commands ac-6
describe("AC-6: kspec agent status shows invocations", () => {
  it("shows active and queued invocation counts", () => {
    // Without daemon, status should show daemon not running info
    const result = kspec("agent status", tempDir, { expectFail: true });
    // When daemon is offline, either error or zero-invocation state
    // The command either exits non-zero or outputs zeros
    expect([0, 3]).toContain(result.exitCode);
  });
});

// ─── Trait: JSON output ───────────────────────────────────────────────────────

// AC: @trait-json-output ac-4
describe("JSON output uses @ prefix for references", () => {
  it("agent list JSON output does not show bare references (agents have IDs not refs)", () => {
    const data = kspecJson<{ items: Array<{ id: string }> }>("agent list", tempDir);
    // Agent IDs are strings without @ prefix (they are not kspec refs)
    for (const item of data.items) {
      expect(typeof item.id).toBe("string");
    }
  });
});

// AC: @trait-semantic-exit-codes ac-4
describe("Runtime errors exit with code 3", () => {
  it("exits with non-zero code when project not found", async () => {
    const { mkdtemp } = await import("node:fs/promises");
    const { join } = await import("node:path");
    const { tmpdir } = await import("node:os");

    const emptyDir = await mkdtemp(join(tmpdir(), "kspec-no-project-"));
    initGitRepo(emptyDir);

    try {
      const result = kspec("agent list", emptyDir, { expectFail: true });
      expect(result.exitCode).not.toBe(0);
    } finally {
      await cleanupTempDir(emptyDir);
    }
  });
});

// AC: @trait-filterable-list ac-8 — count mode in JSON
describe("trait-filterable-list ac-8: --count in JSON mode", () => {
  it("JSON output from --count includes count field as number", () => {
    const result = kspec("agent list --count --json", tempDir);
    expect(result.exitCode).toBe(0);
    const data = JSON.parse(result.stdout);
    expect(typeof data.count).toBe("number");
    expect(data.count).toBeGreaterThan(0);
  });
});

